import { NextRequest, NextResponse } from 'next/server';

// Reject requests containing illegal Unicode normalization sequences in route parameters
const FORBIDDEN_BYTE_PATTERNS = /[\u00DF\u1E9E\u0000-\u001F]/;

export function middleware(req: NextRequest) {
  const url = req.nextUrl;
  const queryKeys = Array.from(url.searchParams.keys());

  for (const key of queryKeys) {
    if (FORBIDDEN_BYTE_PATTERNS.test(key)) {
      return new NextResponse('Bad Request: Invalid Parameter Encoding', {
        status: 400,
        headers: { 'Content-Type': 'text/plain' },
      });
    }
  }

  // Verify path components do not contain hidden expansion characters
  if (FORBIDDEN_BYTE_PATTERNS.test(url.pathname)) {
    return new NextResponse('Bad Request: Invalid Path Encoding', { status: 400 });
  }

  return NextResponse.next();
}

export const config = {
  matcher: '/:path*',
};
